// Neon Hub: open the hub editor for a new hub page.
// Works from the hotbar, Neon Combat Manager's Action HUD, a Neon Hub page button or an active tile.
const hub = game.modules.get("cpr-neon-hub")?.api;
if (!hub) return ui.notifications.warn("Neon Hub isn't active in this world.");
if (!game.user.isGM) return ui.notifications.warn("New Hub Page is for the GM.");
const who = (typeof actor !== "undefined" && actor) || (typeof character !== "undefined" && character) || null;
return hub.editHub();
